arguments.command:
export DRIVE_SESSION_TAG="nothingness_linux_debug"; export DRIVE_TARGET=linux; export DRIVE_RUN_LOG="/tmp/flutter_run_${DRIVE_SESSION_TAG}.log"; export DRIVE_FLUTTER_FIFO="/tmp/flutter_input_${DRIVE_SESSION_TAG}"; export DRIVE_DESKTOP_HOME="/tmp/nothingness_${DRIVE_SESSION_TAG}"; D=.claude/skills/agent-emulator-debugging/scripts/drive.py; 
set -e
$D call ext.nothingness.dragByKey key=hero-seek dx=600 dy=0 steps=120 end=false > .tmp/drag_mid.txt 2>&1 || { cat .tmp/drag_mid.txt; exit 1; }
$D shoot seek_scrub_during
# Close the gesture so temporary feedback clears.
$D call ext.nothingness.dragByKey key=hero-seek dx=1 dy=0 steps=1 end=true > .tmp/drag_end.txt 2>&1 || { cat .tmp/drag_end.txt; exit 1; }
$D shoot seek_scrub_post

